(1113309, 137254, 13688, '<td valign="top">Really, really  like the top half without the northbound line of headlites.  I think I know where you had to take this from so the blur at the bottom was a bit invetibable from the telephoto from the distance.  Nice to see another tampa entrant.</td>', 'Really, really  like the top half without the northbound line of headlites.  I think I know where you had to take this from so the blur at the bottom was a bit invetibable from the telephoto from the distance.  Nice to see another tampa entrant.', '2005-01-17 00:38:04.000000', NULL, 1),
(1113310, 136379, 6804, '<td valign="top">This is a great shot of the City and County blilding. The sun low on the horizon gives it a warm and dramatic cast of light. The soft focus on the branches works well and helps to frame the subject. A couple of the branches are almost a little too soft for me when they start to double, but I do like them in the picture. I might have cloned out the one on the right and the lowest one on the left, just leaving the pine needles.  This building holds a lot of history and brings back some childhood memories.  It''s well shot, and a pleasure to see this one in the challenge.  9</td>', 'This is a great shot of the City and County blilding. The sun low on the horizon gives it a warm and dramatic cast of light. The soft focus on the branches works well and helps to frame the subject. A couple of the branches are almost a little too soft for me when they start to double, but I do like them in the picture. I might have cloned out the one on the right and the lowest one on the left, just leaving the pine needles.  This building holds a lot of history and brings back some childhood memories.  It''s well shot, and a pleasure to see this one in the challenge.  9', '2005-01-17 00:38:20.000000', NULL, 1),
(1113321, 136598, 25232, '<td valign="top">qualifys more a s a landscape.</td>', 'qualifys more a s a landscape.', '2005-01-17 00:40:10.000000', NULL, 1),
