INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1115051, 136780, 30818, '<td valign="top">Too bad there''s an air conditioner hangin out the window...  But that''s not the fault of your photographic skills, so it won''t hurt your score :)</td>', 'Too bad there''s an air conditioner hangin out the window...  But that''s not the fault of your photographic skills, so it won''t hurt your score :)', '2005-01-17 16:20:33.000000', NULL, 1),
(1115070, 136798, 26756, '<td valign="top">Interesting photo.  You managed to take something that potentially could have been really messy and give it some structure.  Great use of angles, lines and colors.</td>', 'Interesting photo.  You managed to take something that potentially could have been really messy and give it some structure.  Great use of angles, lines and colors.', '2005-01-17 16:30:05.000000', NULL, 1),
(1115105, 136796, 26756, '<td valign="top">I very much like the triangular shape, the railing and the tone you chose for this photo.  Good work.</td>', 'I very much like the triangular shape, the railing and the tone you chose for this photo.  Good work.', '2005-01-17 16:45:02.000000', NULL, 1),
(1115113, 137091, 30392, '<td valign="top">Excellent shot, I love the perfect symmetry</td>', 'Excellent shot, I love the perfect symmetry', '2005-01-17 16:48:37.000000', NULL, 1),
(1115121, 137214, 30392, '<td valign="top">good idea, it works well</td>', 'good idea, it works well', '2005-01-17 16:51:14.000000', NULL, 1),
(1115149, 136346, 28108, '<td valign="top">This is one of the very, very rare picture that I find the tilt interesting, you broke the rule it pays off. Also with the wide angle, it creates a unique perspective.</td>', 'This is one of the very, very rare picture that I find the tilt interesting, you broke the rule it pays off. Also with the wide angle, it creates a unique perspective.', '2005-01-17 17:03:02.000000', NULL, 1),
(1115157, 136159, 32111, '<td valign="top">Excellent image.</td>', 'Excellent image.', '2005-01-17 17:07:40.000000', NULL, 1),
(1115164, 136780, 28108, '<td valign="top">It''s too bad the modern (ugly) light post and the air conditionner on the right were there. Also too bad that you couln''t include the whole right part of the building itself (but I understand it can be quite hard unless you have a wide angle). I dolike the angle at wich it was shot.</td>', 'It''s too bad the modern (ugly) light post and the air conditionner on the right were there. Also too bad that you couln''t include the whole right part of the building itself (but I understand it can be quite hard unless you have a wide angle). I dolike the angle at wich it was shot.', '2005-01-17 17:10:11.000000', NULL, 1),
(1115171, 137139, 32111, '<td valign="top">I really like this for some reason. The white building through the arch is a bit distracting for me, but not the end of the world!</td>', 'I really like this for some reason. The white building through the arch is a bit distracting for me, but not the end of the world!', '2005-01-17 17:13:14.000000', NULL, 1),
(1115173, 135736, 28108, '<td valign="top">Over-exposed. I bet there''s a lot of details missing.</td>', 'Over-exposed. I bet there''s a lot of details missing.', '2005-01-17 17:13:46.000000', NULL, 1),
(1115179, 136316, 32111, '<td valign="top">Brilliant image, maybe a wee bit dark - but that may well be my monitor calibration.</td>', 'Brilliant image, maybe a wee bit dark - but that may well be my monitor calibration.', '2005-01-17 17:15:21.000000', NULL, 1),
(1115189, 137237, 17507, '<td valign="top">Nice abstraction. I find the patch of sky a bit distracting, but otherwise I like this.</td>', 'Nice abstraction. I find the patch of sky a bit distracting, but otherwise I like this.', '2005-01-17 17:18:15.000000', NULL, 1),
(1115193, 137187, 31606, '<td valign="top">I would have liked it better had the whole door been in the picture.</td>', 'I would have liked it better had the whole door been in the picture.', '2005-01-17 17:20:00.000000', NULL, 1),
(1115201, 136889, 31606, '<td valign="top">I like it.  Maybe it would look better if lees of the building was in the shot.</td>', 'I like it.  Maybe it would look better if lees of the building was in the shot.', '2005-01-17 17:23:19.000000', NULL, 1),
(1115204, 136968, 31606, '<td valign="top">Great shot.  I love the sky and would love to see this in color.</td>', 'Great shot.  I love the sky and would love to see this in color.', '2005-01-17 17:23:44.000000', NULL, 1),
(1115206, 137169, 31606, '<td valign="top">What beautiful colors in the sky.</td>', 'What beautiful colors in the sky.', '2005-01-17 17:24:27.000000', NULL, 1),
(1115209, 136994, 31606, '<td valign="top">I would like to know where this was taken.  Nice photo.</td>', 'I would like to know where this was taken.  Nice photo.', '2005-01-17 17:25:30.000000', NULL, 1),
(1115211, 136663, 32111, '<td valign="top">People try these kind of shots often, but don''t always get it right - this is very well done.</td>', 'People try these kind of shots often, but don''t always get it right - this is very well done.', '2005-01-17 17:25:57.000000', NULL, 1),
(1115213, 135122, 17507, '<td valign="top">Haha. This entry made me giggle. Thanks for the dose of humor :)</td>', 'Haha. This entry made me giggle. Thanks for the dose of humor :)', '2005-01-17 17:27:15.000000', NULL, 1),
(1115218, 137080, 17507, '<td valign="top">Yay fish tank architecture!! &lt;3</td>', 'Yay fish tank architecture!! <3', '2005-01-17 17:29:41.000000', NULL, 1),
(1115219, 137168, 17507, '<td valign="top">The most interesting thing about this picture is the color. The roof dome looks like oxidized copper, but against the very dark blue sky it looks very surreal.</td>', 'The most interesting thing about this picture is the color. The roof dome looks like oxidized copper, but against the very dark blue sky it looks very surreal.', '2005-01-17 17:31:28.000000', NULL, 1),
(1115222, 136754, 17507, '<td valign="top">Very Interesting Weird Place. It''s good that you have the people there for a sense of scale. Too bad you couldn''t have cropped out the car on the right.</td>', 'Very Interesting Weird Place. It''s good that you have the people there for a sense of scale. Too bad you couldn''t have cropped out the car on the right.', '2005-01-17 17:32:07.000000', NULL, 1),
(1115238, 136912, 17507, '<td valign="top">Great color and detail. If this isn''t in the top 10 I will be very surprised. Half expect it to be in the top 3- but you never know. Haven''t looked at everything yet, and voters are finicky. I''m giving this my first 10 in a while.</td>', 'Great color and detail. If this isn''t in the top 10 I will be very surprised. Half expect it to be in the top 3- but you never know. Haven''t looked at everything yet, and voters are finicky. I''m giving this my first 10 in a while.', '2005-01-17 17:40:23.000000', NULL, 1),
(1115239, 136942, 17507, '<td valign="top">Great title :)</td>', 'Great title :)', '2005-01-17 17:40:39.000000', NULL, 1),
(1115240, 136247, 17507, '<td valign="top">Ah, unmistakably San Francisco :)</td>', 'Ah, unmistakably San Francisco :)', '2005-01-17 17:41:14.000000', NULL, 1),
(1115243, 136778, 17507, '<td valign="top">Nice juxtaposition. Critically speaking, I find myself wishing (1) that the image were in better focus and (2) that the chimney and tree were more central in the composition. The chimney is a bit too far to the left and creates tension with the border.</td>', 'Nice juxtaposition. Critically speaking, I find myself wishing (1) that the image were in better focus and (2) that the chimney and tree were more central in the composition. The chimney is a bit too far to the left and creates tension with the border.', '2005-01-17 17:42:22.000000', NULL, 1),
(1115275, 137222, 14700, '<td valign="top">Not a bad subject..... but needs more contrast and the horizon is not level.</td>', 'Not a bad subject..... but needs more contrast and the horizon is not level.', '2005-01-17 17:54:06.000000', NULL, 1),
(1115280, 136949, 14700, '<td valign="top">The dark shadow on the side of the church sorta spoils it.  I''m guessing it was a cloud.... if it was it would have been nice to wait for it pass.  If it was a tree I suppose there was nothing you could do..... anywho, I''m a sucker for these old church buildings. 7.</td>', 'The dark shadow on the side of the church sorta spoils it.  I''m guessing it was a cloud.... if it was it would have been nice to wait for it pass.  If it was a tree I suppose there was nothing you could do..... anywho, I''m a sucker for these old church buildings. 7.', '2005-01-17 17:57:37.000000', NULL, 1),
(1115283, 136460, 14700, '<td valign="top">Incredible.  I love the color.  Your subject is creative also. 9.</td>', 'Incredible.  I love the color.  Your subject is creative also. 9.', '2005-01-17 17:58:35.000000', NULL, 1),
(1115285, 136754, 14700, '<td valign="top">Very cleaver.</td>', 'Very cleaver.', '2005-01-17 17:59:13.000000', NULL, 1),
(1115289, 136292, 14700, '<td valign="top">Nice subject.  Photo looks a little soft or out of focus.  If it was sharper and had more contrast I think you would have a terrific pic.</td>', 'Nice subject.  Photo looks a little soft or out of focus.  If it was sharper and had more contrast I think you would have a terrific pic.', '2005-01-17 18:00:55.000000', NULL, 1),
(1115291, 136976, 14700, '<td valign="top">I think I found the winner.</td>', 'I think I found the winner.', '2005-01-17 18:01:23.000000', NULL, 1),
(1115295, 135752, 14700, '<td valign="top">This is a terrific interpretation of the challenge.  Brilliant.</td>', 'This is a terrific interpretation of the challenge.  Brilliant.', '2005-01-17 18:02:54.000000', NULL, 1),
(1115297, 137120, 14700, '<td valign="top">Great subject.  Taking it at night added alot.  I think it needs a little more contrast to meets its potential.</td>', 'Great subject.  Taking it at night added alot.  I think it needs a little more contrast to meets its potential.', '2005-01-17 18:05:01.000000', NULL, 1),
(1115304, 137010, 14700, '<td valign="top">I think the sun is on the wrong side of the building to really capture its texture.  If it were taken at a differnt time of day or on the other side of the building I think it would have been stronger.</td>', 'I think the sun is on the wrong side of the building to really capture its texture.  If it were taken at a differnt time of day or on the other side of the building I think it would have been stronger.', '2005-01-17 18:08:44.000000', NULL, 1),
(1115307, 137003, 14700, '<td valign="top">I think it would be stronger with more contrast.</td>', 'I think it would be stronger with more contrast.', '2005-01-17 18:09:56.000000', NULL, 1),
