(1115314, 137131, 32111, '<td valign="top">This is a great shot!  I keep being drawn to the slightest imbalance in the symmetry though? Not sure what it is - perhaps a tiny anticlockwise rotation is needed, not sure...</td>', 'This is a great shot!  I keep being drawn to the slightest imbalance in the symmetry though? Not sure what it is - perhaps a tiny anticlockwise rotation is needed, not sure...', '2005-01-17 18:14:45.000000', NULL, 1),
(1115316, 136371, 3102, '<td valign="top">Never heard of it!  :)</td>', 'Never heard of it!  :)', '2005-01-17 18:15:38.000000', NULL, 1),
(1115321, 136900, 32111, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2005-01-17 18:19:08.000000', NULL, 1),
