(1115537, 135448, 25742, '<td valign="top">Escher über alles. Funny</td>', 'Escher über alles. Funny', '2005-01-17 20:34:33.000000', NULL, 1),
(1115542, 137009, 25742, '<td valign="top">With nothing to compare the hut to, it''s really difiicult to tell what is warped in RL and what is a lens artifact. Have somebody standing next to it for scale and "levelness"</td>', 'With nothing to compare the hut to, it''s really difiicult to tell what is warped in RL and what is a lens artifact. Have somebody standing next to it for scale and "levelness"', '2005-01-17 20:37:16.000000', NULL, 1),
