(1119524, 137251, 22970, '<td valign="top">Nice picture. My wife and I stayed there for a week in 200 and your picture looks the same as it did then. Great job</td>', 'Nice picture. My wife and I stayed there for a week in 200 and your picture looks the same as it did then. Great job', '2005-01-19 15:58:03.000000', NULL, 1),
(1119543, 136749, 24642, '<td valign="top">I like the viewpoint and the visual idea.  Good work with reflections, texture and contrasts.</td>', 'I like the viewpoint and the visual idea.  Good work with reflections, texture and contrasts.', '2005-01-19 16:09:08.000000', NULL, 1),
