(1121078, 136936, 32178, '<td valign="top">This would have been a very good picture, if it just wasnt that dark.<br/>i</td>', 'This would have been a very good picture, if it just wasnt that dark.i', '2005-01-20 09:07:41.000000', NULL, 1),
(1121082, 136159, 32178, '<td valign="top">i would personaly cut a bit of the bottom and left more of the sky, this way its like the trees are more importent then the sky <br/></td>', 'i would personaly cut a bit of the bottom and left more of the sky, this way its like the trees are more importent then the sky ', '2005-01-20 09:10:02.000000', NULL, 1),
(1121088, 137204, 32178, '<td valign="top">A good choice, but i would probaly have made it abit darker and then B&amp;W to give it some extra depth but good picture. <br/></td>', 'A good choice, but i would probaly have made it abit darker and then B&W to give it some extra depth but good picture. ', '2005-01-20 09:17:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1121108, 137148, 23478, '<td valign="top">Excellent... I like the shadows &amp; contrast.</td>', 'Excellent... I like the shadows & contrast.', '2005-01-20 09:37:14.000000', NULL, 1),
(1121110, 137060, 23478, '<td valign="top">Good B&amp;W...</td>', 'Good B&W...', '2005-01-20 09:38:27.000000', NULL, 1),
(1121115, 136707, 23478, '<td valign="top">Excellent angle and the shadow works well.</td>', 'Excellent angle and the shadow works well.', '2005-01-20 09:43:13.000000', NULL, 1),
(1121116, 136289, 23478, '<td valign="top">Very nice.</td>', 'Very nice.', '2005-01-20 09:44:01.000000', NULL, 1),
(1121152, 135448, 1202, '<td valign="top">Very creative, I wonder how many will really "see"  this.</td>', 'Very creative, I wonder how many will really "see"  this.', '2005-01-20 10:39:19.000000', NULL, 1),
(1121160, 136346, 1202, '<td valign="top">I don''t like the tilt. Your wide angle would have carried this shot on the level IMO.</td>', 'I don''t like the tilt. Your wide angle would have carried this shot on the level IMO.', '2005-01-20 10:46:11.000000', NULL, 1),
(1121165, 137120, 1202, '<td valign="top">OOPS, where did the top go?  I think you needed it here.</td>', 'OOPS, where did the top go?  I think you needed it here.', '2005-01-20 10:48:13.000000', NULL, 1),
(1121168, 136699, 1202, '<td valign="top">I think I wish this wern''t so dark.  I am sure it was your intent but it doesn''t work for me.</td>', 'I think I wish this wern''t so dark.  I am sure it was your intent but it doesn''t work for me.', '2005-01-20 10:49:56.000000', NULL, 1),
(1121172, 136762, 1202, '<td valign="top">Very interesting shot. At least you had sun!!</td>', 'Very interesting shot. At least you had sun!!', '2005-01-20 10:51:28.000000', NULL, 1),
(1121178, 136598, 1202, '<td valign="top">If ya gotta tell me it didn''t do it on its own.  Sorry this time.</td>', 'If ya gotta tell me it didn''t do it on its own.  Sorry this time.', '2005-01-20 10:54:06.000000', NULL, 1),
(1121183, 136159, 1202, '<td valign="top">Very nice.  Good eye and great angle. Lucky you had a little color in the sky.</td>', 'Very nice.  Good eye and great angle. Lucky you had a little color in the sky.', '2005-01-20 10:55:48.000000', NULL, 1),
(1121188, 136944, 1202, '<td valign="top">Great color mix and wonderful angle. Top shot IMO</td>', 'Great color mix and wonderful angle. Top shot IMO', '2005-01-20 10:58:21.000000', NULL, 1),
(1121201, 137012, 1202, '<td valign="top">What a wonderful subject and a nice view. Nit pick, but I think cropped too close on the right.  In this case both should be exactly equal.  One of the top shots IMO.</td>', 'What a wonderful subject and a nice view. Nit pick, but I think cropped too close on the right.  In this case both should be exactly equal.  One of the top shots IMO.', '2005-01-20 11:02:43.000000', NULL, 1),
(1121209, 136472, 1202, '<td valign="top">Great subject. I wonder if your angle of approach could have been different to give it more power/impact. Probably out of the box for DPC folks. 8</td>', 'Great subject. I wonder if your angle of approach could have been different to give it more power/impact. Probably out of the box for DPC folks. 8', '2005-01-20 11:07:47.000000', NULL, 1),
(1121211, 136994, 1202, '<td valign="top">I sure would have liked this one more if it were a bit brighter in the lower portion of the shot.  Great subject, good angle, super sky.</td>', 'I sure would have liked this one more if it were a bit brighter in the lower portion of the shot.  Great subject, good angle, super sky.', '2005-01-20 11:11:17.000000', NULL, 1),
(1121227, 136464, 1202, '<td valign="top">I think if you had just used the wonderful lines formed by the top portion of the building it would be super.  The bright lights and traffic distract from this greatly.</td>', 'I think if you had just used the wonderful lines formed by the top portion of the building it would be super.  The bright lights and traffic distract from this greatly.', '2005-01-20 11:25:24.000000', NULL, 1),
(1121239, 135276, 1202, '<td valign="top">Superb use of existing components in your composition.  Its on the drak and dreary side but still commands high score.</td>', 'Superb use of existing components in your composition.  Its on the drak and dreary side but still commands high score.', '2005-01-20 11:29:11.000000', NULL, 1),
(1121250, 137154, 1202, '<td valign="top">You didn''t have to tell us, bad title, wonderful shot. 8</td>', 'You didn''t have to tell us, bad title, wonderful shot. 8', '2005-01-20 11:33:12.000000', NULL, 1),
(1121308, 137214, 29462, '<td valign="top">Very cool love it</td>', 'Very cool love it', '2005-01-20 12:11:26.000000', NULL, 1),
(1121315, 137182, 29462, '<td valign="top">Great love the symetry cant make my mind up whether I like the bottom left detail in or cropped out. Nice composition.</td>', 'Great love the symetry cant make my mind up whether I like the bottom left detail in or cropped out. Nice composition.', '2005-01-20 12:13:20.000000', NULL, 1),
(1121316, 137131, 29462, '<td valign="top">Certainly has the wow factor..</td>', 'Certainly has the wow factor..', '2005-01-20 12:13:55.000000', NULL, 1),
(1121548, 137182, 27562, '<td valign="top">Awesome geometric pattern, but i would have either reframed to exclude the balcony or what ever in the lower left hand corner or cropped it out.  Good work.</td>', 'Awesome geometric pattern, but i would have either reframed to exclude the balcony or what ever in the lower left hand corner or cropped it out.  Good work.', '2005-01-20 14:17:08.000000', NULL, 1),
(1121559, 135999, 27562, '<td valign="top">Interesting perspective making excellent use of telephoto compression.</td>', 'Interesting perspective making excellent use of telephoto compression.', '2005-01-20 14:22:06.000000', NULL, 1),
(1121581, 137131, 16106, '<td valign="top">upon reflection I am bumping this shot to the top 3 in my pantheon. I love the framing, allowing the sky enough room to push back against the spires; audacious and lovely. The perfect bi-lateral symetry and cool, almost clinical  color tones will cause some to criticise your composition but this works very well IMHO.</td>', 'upon reflection I am bumping this shot to the top 3 in my pantheon. I love the framing, allowing the sky enough room to push back against the spires; audacious and lovely. The perfect bi-lateral symetry and cool, almost clinical  color tones will cause some to criticise your composition but this works very well IMHO.', '2005-01-20 14:35:26.000000', NULL, 1),
(1121607, 135521, 30364, '<td valign="top">Effective photo of a very worthy architectural detail (and it IS architectural; you can be sure these beautiful steps were designed by the architect and not by the gardener).  I like the B&amp;W treatment because it exploits the glow of the presumably marble steps to lead the viewer through the series of interesting posts/pillars.  8.</td>', 'Effective photo of a very worthy architectural detail (and it IS architectural; you can be sure these beautiful steps were designed by the architect and not by the gardener).  I like the B&W treatment because it exploits the glow of the presumably marble steps to lead the viewer through the series of interesting posts/pillars.  8.', '2005-01-20 14:56:22.000000', NULL, 1),
(1121617, 135926, 30364, '<td valign="top">A slightly different perspective on the dome photo.  It does create some added interest I guess, but perhaps at the expense of a view of the detail of the lower part of the dome (the more visible left-hand side is cropped off).  And this perspective also brings into view the dark part of the small archway at lower right, which to me looks a bit distracting.  But I applaud the attempt at a fresh look at a familiar subject.  6.</td>', 'A slightly different perspective on the dome photo.  It does create some added interest I guess, but perhaps at the expense of a view of the detail of the lower part of the dome (the more visible left-hand side is cropped off).  And this perspective also brings into view the dark part of the small archway at lower right, which to me looks a bit distracting.  But I applaud the attempt at a fresh look at a familiar subject.  6.', '2005-01-20 15:04:38.000000', NULL, 1),
(1121624, 137126, 30364, '<td valign="top">This is very appealing photo with a deceptively simple composition.  But I don''t feel it''s really got much to do with architecture.  Still ... 6</td>', 'This is very appealing photo with a deceptively simple composition.  But I don''t feel it''s really got much to do with architecture.  Still ... 6', '2005-01-20 15:07:26.000000', NULL, 1),
(1121636, 136247, 30364, '<td valign="top">I understand your point (excuse the pun), but I''m afraid I feel the idea doesn''t really do either building justice.  To me, it nearly works, but not quite.  Sorry!  4.</td>', 'I understand your point (excuse the pun), but I''m afraid I feel the idea doesn''t really do either building justice.  To me, it nearly works, but not quite.  Sorry!  4.', '2005-01-20 15:16:09.000000', NULL, 1),
(1121653, 136749, 30364, '<td valign="top">It''s a very interesting image which confused me at first glance.  The rustic planetarium dome &amp; the launch-pad like modern building work very well together (IS it a building?  Does it house some astronomical gizmo?  See, I''m still confused).  7.</td>', 'It''s a very interesting image which confused me at first glance.  The rustic planetarium dome & the launch-pad like modern building work very well together (IS it a building?  Does it house some astronomical gizmo?  See, I''m still confused).  7.', '2005-01-20 15:21:11.000000', NULL, 1),
(1121661, 137157, 30364, '<td valign="top">So it''s a burial mound?  I wish I could be more impressed, but it looks like a stack of silage on a dairy farm.  But if it is what I guessed, it is a real challenge ... a damned inspiring subject which doesn''t look very significant from any angle.  So I guess you did as well as could be expected!  5.</td>', 'So it''s a burial mound?  I wish I could be more impressed, but it looks like a stack of silage on a dairy farm.  But if it is what I guessed, it is a real challenge ... a damned inspiring subject which doesn''t look very significant from any angle.  So I guess you did as well as could be expected!  5.', '2005-01-20 15:25:25.000000', NULL, 1),
(1121670, 137168, 30364, '<td valign="top">This is a nice treatment of a beautiful dome.  I felt the bottom (non-dome) part of the building detracted from the impact, but when I tried the effect of other crops I couldn''t do any better.   6.</td>', 'This is a nice treatment of a beautiful dome.  I felt the bottom (non-dome) part of the building detracted from the impact, but when I tried the effect of other crops I couldn''t do any better.   6.', '2005-01-20 15:29:11.000000', NULL, 1),
(1121676, 136443, 30364, '<td valign="top">This is a very nice architectural detail which does just what a detail should ... it reveals or amplifies something about the character of the building.  7.</td>', 'This is a very nice architectural detail which does just what a detail should ... it reveals or amplifies something about the character of the building.  7.', '2005-01-20 15:32:01.000000', NULL, 1),
(1121686, 137204, 30364, '<td valign="top">You''ve got to think NASA when you see this, not Port Phillip Bay.  It''s an elegantly composed photograph of distinctive structure.  6.</td>', 'You''ve got to think NASA when you see this, not Port Phillip Bay.  It''s an elegantly composed photograph of distinctive structure.  6.', '2005-01-20 15:36:47.000000', NULL, 1),
(1121691, 137154, 30364, '<td valign="top">The other building looks Egyptian.  Or Dali.  Interesting effect for sure, but doesn''t seem to stimulate me into thinking about anything architectural.  Perhaps that''s my problem &amp; not yours.  6.</td>', 'The other building looks Egyptian.  Or Dali.  Interesting effect for sure, but doesn''t seem to stimulate me into thinking about anything architectural.  Perhaps that''s my problem & not yours.  6.', '2005-01-20 15:39:33.000000', NULL, 1),
(1121701, 136327, 30364, '<td valign="top">The processing is not to my taste, but I have to admit it makes this scene very striking.  If the "present" is the rail bridge, it seems to be nearly past it as well!.  To me it''s not a great architectural shot, but it is a very appealing image anyway.  6.</td>', 'The processing is not to my taste, but I have to admit it makes this scene very striking.  If the "present" is the rail bridge, it seems to be nearly past it as well!.  To me it''s not a great architectural shot, but it is a very appealing image anyway.  6.', '2005-01-20 15:45:52.000000', NULL, 1),
(1121710, 137182, 30364, '<td valign="top">Well yes it is.  Well done.  7.</td>', 'Well yes it is.  Well done.  7.', '2005-01-20 15:48:24.000000', NULL, 1),
(1121722, 136782, 30364, '<td valign="top">Well done on finding a way to effectively display the architectural essence of what would have seemed to me an overwhelming subject.  The perspective, cropping, and the use of light and colour are highly sympathetic ... the architect would have been very pleased with what you''ve done here.  I like the building &amp; love the photo.  8.</td>', 'Well done on finding a way to effectively display the architectural essence of what would have seemed to me an overwhelming subject.  The perspective, cropping, and the use of light and colour are highly sympathetic ... the architect would have been very pleased with what you''ve done here.  I like the building & love the photo.  8.', '2005-01-20 15:54:47.000000', NULL, 1),
(1121726, 136623, 30364, '<td valign="top">It''s certainly a very architectural photo; even looks like one of those architect''s drawings!  It''s also a very well-conceived &amp; executed view of an interesting building.  7.</td>', 'It''s certainly a very architectural photo; even looks like one of those architect''s drawings!  It''s also a very well-conceived & executed view of an interesting building.  7.', '2005-01-20 15:58:00.000000', NULL, 1),
(1121773, 136992, 30364, '<td valign="top">Effective photograph, due to the impressive reflected building and the unusual window framing it.   Not visually stunning, but it rewards a moment''s contemplation.  6.</td>', 'Effective photograph, due to the impressive reflected building and the unusual window framing it.   Not visually stunning, but it rewards a moment''s contemplation.  6.', '2005-01-20 16:24:13.000000', NULL, 1),
(1121778, 137091, 30364, '<td valign="top">Very impressive symmetry, carefully composed and well executed.  It is an image that is very sympathetic to the building''s architectural personality.  7.</td>', 'Very impressive symmetry, carefully composed and well executed.  It is an image that is very sympathetic to the building''s architectural personality.  7.', '2005-01-20 16:27:30.000000', NULL, 1),
(1121781, 137059, 30364, '<td valign="top">Very impressive image: effective point of view &amp; nice execution.  Great title!  6.</td>', 'Very impressive image: effective point of view & nice execution.  Great title!  6.', '2005-01-20 16:29:33.000000', NULL, 1),
(1121794, 136875, 30364, '<td valign="top">I don''t particularly like it as an image .. I may of course just be too conservative to appreciate it.  But it is certainly worth a few minutes'' study, which is no bad accomplishment in itself; it cannot be readily dismissed.  It''s probably better than I think!  6.</td>', 'I don''t particularly like it as an image .. I may of course just be too conservative to appreciate it.  But it is certainly worth a few minutes'' study, which is no bad accomplishment in itself; it cannot be readily dismissed.  It''s probably better than I think!  6.', '2005-01-20 16:36:25.000000', NULL, 1),
(1121829, 137187, 10432, '<td valign="top">I keep wanting to do shots like this.  Some church doors are so cool looking.  These included.  Your shot seems a bit tilted to the left or maybe you took it from a slight angle instead of dead  on.  I also think you could have panned back a bit to ge the full door plus the window.   Maybe a different time of day would help lessen the shadows.<br/><br/><i>Message edited by author 2005-01-24 01:39:47.</i></td>', 'I keep wanting to do shots like this.  Some church doors are so cool looking.  These included.  Your shot seems a bit tilted to the left or maybe you took it from a slight angle instead of dead  on.  I also think you could have panned back a bit to ge the full door plus the window.   Maybe a different time of day would help lessen the shadows.', '2005-01-20 16:58:37.000000', '2005-01-24 01:39:47.000000', 1),
(1121834, 137249, 10432, '<td valign="top">Nice shot. I love the perspective with the lantern so predominant.  I''m not sure I like the color treatment.  I think b&amp;w or sepia might be better.</td>', 'Nice shot. I love the perspective with the lantern so predominant.  I''m not sure I like the color treatment.  I think b&w or sepia might be better.', '2005-01-20 17:01:46.000000', NULL, 1),
(1121848, 136223, 21621, '<td valign="top">Very cool abstract, might have worked without the angle, maybe upside down or sideways?  Nice work.</td>', 'Very cool abstract, might have worked without the angle, maybe upside down or sideways?  Nice work.', '2005-01-20 17:10:08.000000', NULL, 1),
(1121862, 137049, 23394, '<td valign="top">this looks like it has a lot of potential as a vista to shoot, but for some reason or another, your image seems flat.  6</td>', 'this looks like it has a lot of potential as a vista to shoot, but for some reason or another, your image seems flat.  6', '2005-01-20 17:20:05.000000', NULL, 1),
(1121879, 137249, 23394, '<td valign="top">a little neat image would have gone a long, long, long, long way with this one.  great composition, wonderful lighting.  just wish you had polished it off. 6</td>', 'a little neat image would have gone a long, long, long, long way with this one.  great composition, wonderful lighting.  just wish you had polished it off. 6', '2005-01-20 17:28:09.000000', NULL, 1),
(1121886, 137204, 23394, '<td valign="top">i''ma givin this a 10 because it smacked me in the face after 25 mirrored reflections in a row!  sometimes, that random ordering of images works out in your favor ;-)</td>', 'i''ma givin this a 10 because it smacked me in the face after 25 mirrored reflections in a row!  sometimes, that random ordering of images works out in your favor ;-)', '2005-01-20 17:29:41.000000', NULL, 1),
(1121890, 137080, 23394, '<td valign="top">pm me and tell me what you really think i should score this and why.  otherwise, i''ll leave it at a 2.  sorry for being harsh, but i have a hard time believing that this is the best thing you could come up with to enter.</td>', 'pm me and tell me what you really think i should score this and why.  otherwise, i''ll leave it at a 2.  sorry for being harsh, but i have a hard time believing that this is the best thing you could come up with to enter.', '2005-01-20 17:32:23.000000', NULL, 1),
(1121893, 137109, 23394, '<td valign="top">pretty popular building...</td>', 'pretty popular building...', '2005-01-20 17:33:20.000000', NULL, 1),
(1121982, 136880, 11793, '<td valign="top">it''s kind of busy.<br/></td>', 'it''s kind of busy.', '2005-01-20 18:32:52.000000', NULL, 1),
(1122043, 137060, 30364, '<td valign="top">This is a very good architectural detail.  It manages to include several of the significant design devices that help define this building, but the photograph still doesn''t seem too crowded or contrived.  And in addition to its challenge-related merits, it is also a very effective and original composition, well photographed and then processed in a fashion sympathetic to the subject.   8.</td>', 'This is a very good architectural detail.  It manages to include several of the significant design devices that help define this building, but the photograph still doesn''t seem too crowded or contrived.  And in addition to its challenge-related merits, it is also a very effective and original composition, well photographed and then processed in a fashion sympathetic to the subject.   8.', '2005-01-20 19:33:30.000000', NULL, 1),
(1122052, 136877, 30364, '<td valign="top">Maybe it''s the tilt it''s on?  Sorry; kidding.  The photograph doesn''t, for me, convey much about the house''s design or character.  And is it out of focus or have you just used a blur filter effect?  Either way, it doesn''t help the image for me.  Sorry.  4.</td>', 'Maybe it''s the tilt it''s on?  Sorry; kidding.  The photograph doesn''t, for me, convey much about the house''s design or character.  And is it out of focus or have you just used a blur filter effect?  Either way, it doesn''t help the image for me.  Sorry.  4.', '2005-01-20 19:36:58.000000', NULL, 1),
(1122053, 137207, 30364, '<td valign="top">Good photograph of this subject, taken at the right time of day.  6</td>', 'Good photograph of this subject, taken at the right time of day.  6', '2005-01-20 19:37:58.000000', NULL, 1),
(1122064, 135691, 30364, '<td valign="top">Striking image of a bizarre structure.  But somehow the major emotion you''ve created for me is confusion (situation normal, some would say).  I''d like it more if your photo revealed a bit more, because the structure is so unusual that my experience can''t fill in the gaps (I mean I can''t see just this bit of it and say "Oh yes, that''s an interesting detail shot of ............."). Hence confused.  5.</td>', 'Striking image of a bizarre structure.  But somehow the major emotion you''ve created for me is confusion (situation normal, some would say).  I''d like it more if your photo revealed a bit more, because the structure is so unusual that my experience can''t fill in the gaps (I mean I can''t see just this bit of it and say "Oh yes, that''s an interesting detail shot of ............."). Hence confused.  5.', '2005-01-20 19:43:06.000000', NULL, 1),
(1122071, 136901, 30364, '<td valign="top">It''s a moderately interesting photo, even if it tells me more about the owner than the architect.  But there''s nothing to hold my interest, I''m afraid.  One glance &amp; I have absorbed all it has to say to me.  Sorry.  5.</td>', 'It''s a moderately interesting photo, even if it tells me more about the owner than the architect.  But there''s nothing to hold my interest, I''m afraid.  One glance & I have absorbed all it has to say to me.  Sorry.  5.', '2005-01-20 19:45:33.000000', NULL, 1),
(1122082, 135596, 30364, '<td valign="top">Well the buildings are undistinguished, but I like the window glass.  The photo is OK, but I''m afraid it doesn''t really capture my interest.  It''s a good shot in many ways, I just feel it doesn''t have one special property to give it more impact.  Sorry.  5.</td>', 'Well the buildings are undistinguished, but I like the window glass.  The photo is OK, but I''m afraid it doesn''t really capture my interest.  It''s a good shot in many ways, I just feel it doesn''t have one special property to give it more impact.  Sorry.  5.', '2005-01-20 19:51:24.000000', NULL, 1),
(1122089, 137247, 30364, '<td valign="top">Very high-impact image of a dramatic building.  The reflected forebear is very good here, and the foreground adds to the way the image works for the viewer.  7.</td>', 'Very high-impact image of a dramatic building.  The reflected forebear is very good here, and the foreground adds to the way the image works for the viewer.  7.', '2005-01-20 19:54:57.000000', NULL, 1),
(1122163, 135999, 30364, '<td valign="top">It''s an intriguing idea that I don''t entirely understand.  I couldn''t ignore it, which must be a good sign.  But whatever it does have to tell me is about something other than architecture.  Sorry (especially as I may not be doing it justice).  5.</td>', 'It''s an intriguing idea that I don''t entirely understand.  I couldn''t ignore it, which must be a good sign.  But whatever it does have to tell me is about something other than architecture.  Sorry (especially as I may not be doing it justice).  5.', '2005-01-20 20:47:46.000000', NULL, 1),
(1122207, 136122, 30364, '<td valign="top">This is a truly beautiful photograph, in the style of an Andrew Wyeth painting.  It is a wonderful, restrained architectural study for two reasons.  First, it showcases the elegant simplicity of this rural cottage, and cleverly uses just a part of it to do so.  And second, it effortlessly establishes the perfect harmony of the cottage with its environment.  And of course, it''s a terrific photographic work even without the architectural considerations.  No choice here for me ... it''s a 10.</td>', 'This is a truly beautiful photograph, in the style of an Andrew Wyeth painting.  It is a wonderful, restrained architectural study for two reasons.  First, it showcases the elegant simplicity of this rural cottage, and cleverly uses just a part of it to do so.  And second, it effortlessly establishes the perfect harmony of the cottage with its environment.  And of course, it''s a terrific photographic work even without the architectural considerations.  No choice here for me ... it''s a 10.', '2005-01-20 21:07:40.000000', NULL, 1),
(1122211, 136032, 30364, '<td valign="top">I think the night-time image does not do this impressive building justice, because too much detail is lost in the darkness and the digital noise.  The remaining image is, to me, left a bit two-dimensional.  Sorry.  4.</td>', 'I think the night-time image does not do this impressive building justice, because too much detail is lost in the darkness and the digital noise.  The remaining image is, to me, left a bit two-dimensional.  Sorry.  4.', '2005-01-20 21:10:14.000000', NULL, 1),
(1122214, 136949, 30364, '<td valign="top">Curse that shadow!  Without it, a higher score.  But it''s just too much distraction for me.  Sorry.  5.</td>', 'Curse that shadow!  Without it, a higher score.  But it''s just too much distraction for me.  Sorry.  5.', '2005-01-20 21:11:23.000000', NULL, 1),
(1122216, 137251, 30364, '<td valign="top">Just too confused to appeal to me. Much like Las Vegas, I imagine.  Sorry. 4.</td>', 'Just too confused to appeal to me. Much like Las Vegas, I imagine.  Sorry. 4.', '2005-01-20 21:12:40.000000', NULL, 1),
(1122219, 136030, 30364, '<td valign="top">Too confused to work as an architectural detail study, in my view.  All it tells me about this building is that I don''t want to visit it.  On the other hand, it is an interesting and skilful photograph.  5.</td>', 'Too confused to work as an architectural detail study, in my view.  All it tells me about this building is that I don''t want to visit it.  On the other hand, it is an interesting and skilful photograph.  5.', '2005-01-20 21:15:30.000000', NULL, 1),
(1122222, 136598, 30364, '<td valign="top">Naaah.  You could just as well have said it was Julie Andrews on the horizon &amp; entered it in Movie Titles as "My Fair Lady".  Sorry.  4.</td>', 'Naaah.  You could just as well have said it was Julie Andrews on the horizon & entered it in Movie Titles as "My Fair Lady".  Sorry.  4.', '2005-01-20 21:18:25.000000', NULL, 1),
(1122226, 136627, 30364, '<td valign="top">Not strictly architecture, but close enough.  It''s a very nice composition, but I''m afraid that it appears too heavily processed for me, diminishing whatever character it may have had.  Sorry.  4.</td>', 'Not strictly architecture, but close enough.  It''s a very nice composition, but I''m afraid that it appears too heavily processed for me, diminishing whatever character it may have had.  Sorry.  4.', '2005-01-20 21:25:07.000000', NULL, 1),
(1122241, 136957, 30364, '<td valign="top">I M Impressed.  With the building and with your photograph of it.  I suppose the off-centre composition was pretty hard to resist, and fortunately you didn''t do so.  So I think you got it just right.  8.</td>', 'I M Impressed.  With the building and with your photograph of it.  I suppose the off-centre composition was pretty hard to resist, and fortunately you didn''t do so.  So I think you got it just right.  8.', '2005-01-20 21:36:56.000000', NULL, 1),
(1122247, 136950, 30364, '<td valign="top">Very effective composition &amp; execution.  I think you have expressed exactly what you intended about this building.  7.</td>', 'Very effective composition & execution.  I think you have expressed exactly what you intended about this building.  7.', '2005-01-20 21:39:23.000000', NULL, 1),
(1122250, 136104, 30364, '<td valign="top">I don''t think it''s architecture at all (I don''t think it''s food, either).  Sorry. 3.</td>', 'I don''t think it''s architecture at all (I don''t think it''s food, either).  Sorry. 3.', '2005-01-20 21:41:17.000000', NULL, 1),
(1122252, 137085, 30364, '<td valign="top">This is very elegantly composed &amp; handles the dramatic range of light in the scene pretty well.  6.</td>', 'This is very elegantly composed & handles the dramatic range of light in the scene pretty well.  6.', '2005-01-20 21:42:35.000000', NULL, 1),
(1122257, 137093, 30364, '<td valign="top">Probably a very appropriate photographic treatment of it, given its provenance.  But it still makes an image of limited interest, however clever your vision of it.  Sorry.  4.</td>', 'Probably a very appropriate photographic treatment of it, given its provenance.  But it still makes an image of limited interest, however clever your vision of it.  Sorry.  4.', '2005-01-20 21:45:54.000000', NULL, 1),
(1122261, 135166, 23680, '<td valign="top">I really like this, especially the reflection of the one building into another, when I first saw it I thought, what the heck?  Only nitpick would be the line in the sky (can''t tell what it is) on the left hand side about a third of the way down.</td>', 'I really like this, especially the reflection of the one building into another, when I first saw it I thought, what the heck?  Only nitpick would be the line in the sky (can''t tell what it is) on the left hand side about a third of the way down.', '2005-01-20 21:49:12.000000', NULL, 1),
(1122263, 136900, 23680, '<td valign="top">I like the balance in this shot.  Maybe would have left a little more room on the bottom to show the bottom moldings on the windows</td>', 'I like the balance in this shot.  Maybe would have left a little more room on the bottom to show the bottom moldings on the windows', '2005-01-20 21:50:29.000000', NULL, 1),
(1122265, 137089, 30364, '<td valign="top">Very good photograph.  It''s been done before, and often, but yours is a superior version.  Composition is more or less inevitable, but the perfect lighting, your delicate balance of exposure values and the inclusion of an excellent figure all add to the impact of your tribute to this appealing architecture.  8.</td>', 'Very good photograph.  It''s been done before, and often, but yours is a superior version.  Composition is more or less inevitable, but the perfect lighting, your delicate balance of exposure values and the inclusion of an excellent figure all add to the impact of your tribute to this appealing architecture.  8.', '2005-01-20 21:51:06.000000', NULL, 1),
(1122266, 136029, 23680, '<td valign="top">I like the colors a lot, but would like to see it without the wall on the right hand side</td>', 'I like the colors a lot, but would like to see it without the wall on the right hand side', '2005-01-20 21:51:32.000000', NULL, 1),
(1122267, 136223, 23680, '<td valign="top">Wow - those are some colors.  One of my favorites so far, different and imaginative</td>', 'Wow - those are some colors.  One of my favorites so far, different and imaginative', '2005-01-20 21:52:15.000000', NULL, 1),
(1122268, 135736, 23680, '<td valign="top">I usually like this effect, but for this one it loses a lot of what looks like interesting details on the columns</td>', 'I usually like this effect, but for this one it loses a lot of what looks like interesting details on the columns', '2005-01-20 21:53:00.000000', NULL, 1),
(1122269, 137112, 30364, '<td valign="top">Neither of which should ever have been constructed.  Happily, your photo is a bit better than the building.  5.</td>', 'Neither of which should ever have been constructed.  Happily, your photo is a bit better than the building.  5.', '2005-01-20 21:55:14.000000', NULL, 1),
(1122270, 136938, 23680, '<td valign="top">This is a really nice element but it seems to be overshadowed by the white in the upper right corner</td>', 'This is a really nice element but it seems to be overshadowed by the white in the upper right corner', '2005-01-20 21:55:45.000000', NULL, 1),
(1122272, 137152, 23680, '<td valign="top">I like your angle and composition but I don''t think the B&amp;W works for this.  It looks like there might be a lot of interesting colors that I''d like to see</td>', 'I like your angle and composition but I don''t think the B&W works for this.  It looks like there might be a lot of interesting colors that I''d like to see', '2005-01-20 21:57:43.000000', NULL, 1),
(1122275, 136512, 23680, '<td valign="top">I really, really like this, the mood is great</td>', 'I really, really like this, the mood is great', '2005-01-20 21:59:39.000000', NULL, 1),
(1122276, 137190, 30364, '<td valign="top">It has the feel of a fine drawing, or an elaborate pre-computer architectural elevation (not counting the interesting reflections, of course; pre-computer architects weren''t that whimsical).  6.</td>', 'It has the feel of a fine drawing, or an elaborate pre-computer architectural elevation (not counting the interesting reflections, of course; pre-computer architects weren''t that whimsical).  6.', '2005-01-20 21:59:51.000000', NULL, 1),
