(1122281, 137078, 30364, '<td valign="top">Nice architectural detail, with enough of the greater building to give it both scale and context.  6.</td>', 'Nice architectural detail, with enough of the greater building to give it both scale and context.  6.', '2005-01-20 22:00:48.000000', NULL, 1),
(1122290, 136524, 23680, '<td valign="top">Would like to see this without the tree on the left, the darkness draws my eye to it, but other than that, great find :)</td>', 'Would like to see this without the tree on the left, the darkness draws my eye to it, but other than that, great find :)', '2005-01-20 22:04:04.000000', NULL, 1),
(1122294, 137078, 23680, '<td valign="top">Great lines, looks a little soft to me though, sorry</td>', 'Great lines, looks a little soft to me though, sorry', '2005-01-20 22:06:04.000000', NULL, 1),
(1122296, 136780, 23680, '<td valign="top">Nice contrast, this would work for the "old and new" challenge:)</td>', 'Nice contrast, this would work for the "old and new" challenge:)', '2005-01-20 22:06:55.000000', NULL, 1),
(1122297, 136707, 30364, '<td valign="top">Appealing composition, but the shadow severely diminishes the impact. I''d have scored it higher otherwise.  Perhaps there''s no time here with full, suitable light?  5.</td>', 'Appealing composition, but the shadow severely diminishes the impact. I''d have scored it higher otherwise.  Perhaps there''s no time here with full, suitable light?  5.', '2005-01-20 22:08:12.000000', NULL, 1),
(1122301, 137012, 30364, '<td valign="top">Looks like a convention of snails.  Very dramatic photo, though.  6.</td>', 'Looks like a convention of snails.  Very dramatic photo, though.  6.', '2005-01-20 22:09:59.000000', NULL, 1),
(1122311, 136663, 30364, '<td valign="top">Very nice composition and an effective tribute to this fine arched walkway.  I like the fact that you were not tempted to crop off the tops of the first two arches, to avoid the two "see through" fragments.  They add to the interest.  7.</td>', 'Very nice composition and an effective tribute to this fine arched walkway.  I like the fact that you were not tempted to crop off the tops of the first two arches, to avoid the two "see through" fragments.  They add to the interest.  7.', '2005-01-20 22:19:37.000000', NULL, 1),
(1122314, 136442, 30364, '<td valign="top">A bit noisy and a bit tilted, both of which distract me I''m afraid.  4.</td>', 'A bit noisy and a bit tilted, both of which distract me I''m afraid.  4.', '2005-01-20 22:21:31.000000', NULL, 1),
(1122318, 137079, 30364, '<td valign="top">I''m afraid I don''t think this tilted perspective works as well as a more conventional approach.  This is a stately, even ponderous building and, just like a similarly proportioned mature woman, appears alarming when tipped over.  5.</td>', 'I''m afraid I don''t think this tilted perspective works as well as a more conventional approach.  This is a stately, even ponderous building and, just like a similarly proportioned mature woman, appears alarming when tipped over.  5.', '2005-01-20 22:25:35.000000', NULL, 1),
