(1127924, 136976, 25464, '<td valign="top">Interesting, but lacking the necessary crispness to make this a winner IMO.  Very good angle and composition.</td>', 'Interesting, but lacking the necessary crispness to make this a winner IMO.  Very good angle and composition.', '2005-01-23 22:35:15.000000', NULL, 1),
