INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1131983, 135276, 11181, '<td valign="top">Congrats on the blue!!! Well done, extremely well deserved!! Kudos</td>', 'Congrats on the blue!!! Well done, extremely well deserved!! Kudos', '2005-01-25 22:50:41.000000', NULL, 0),
(1132052, 136188, 6630, '<td valign="top">The "circle" was actually egg shaped, it was an oval.<br/> <br/>June</td>', 'The "circle" was actually egg shaped, it was an oval. June', '2005-01-25 23:13:06.000000', NULL, 0),
(1132443, 135276, 8367, '<td valign="top">Congratulations on your first blue ribbon! <br/>Great perspective and the sepia tone suits this so well.</td>', 'Congratulations on your first blue ribbon! Great perspective and the sepia tone suits this so well.', '2005-01-26 01:46:09.000000', NULL, 0),
(1132655, 137083, 11897, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by graphicfunk:</b></div><hr/><i> One eye commentator: Congratualtions on your 12th finish with this rustic viaduct. </i></td></tr></table> <br/> <br/>Lol, thanks Daniel I appreciate all your comments, even one-eyed ones.</td>', 'Originally posted by graphicfunk: One eye commentator: Congratualtions on your 12th finish with this rustic viaduct.   Lol, thanks Daniel I appreciate all your comments, even one-eyed ones.', '2005-01-26 04:48:11.000000', NULL, 0),
(1132727, 135691, 29462, '<td valign="top">Thanks for the comments, very useful.<br/> <br/>Pete</td>', 'Thanks for the comments, very useful. Pete', '2005-01-26 05:45:58.000000', NULL, 0),
(1133718, 137083, 6999, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by graphicfunk:</b></div><hr/><i> One eye commentator: Congratualtions on your 12th finish with this rustic viaduct. </i></td></tr></table> <br/> <br/>''Rustic'' ... I''m not sure it''s quite the word I would have chosen. Still, no surprise.<br/> <br/>Got to the Bramhope Tunnel monument in Otley, and read the details. Go to Chapel-le-Dale churchyard, and read the details. Then go back to Ribblehead and shoot it again. This construction should be photographed in muted tones, against an angry sky. Just one part of the most expensive piece of railway on the planet - including the channel tunnel. That''s if you count in terms of human lives, of course. It''s a good shot, of course, and scores deservingly ... it''s just that i think it should be freighted with it''s history.<br/> <br/>E</td>', 'Originally posted by graphicfunk: One eye commentator: Congratualtions on your 12th finish with this rustic viaduct.   ''Rustic'' ... I''m not sure it''s quite the word I would have chosen. Still, no surprise. Got to the Bramhope Tunnel monument in Otley, and read the details. Go to Chapel-le-Dale churchyard, and read the details. Then go back to Ribblehead and shoot it again. This construction should be photographed in muted tones, against an angry sky. Just one part of the most expensive piece of railway on the planet - including the channel tunnel. That''s if you count in terms of human lives, of course. It''s a good shot, of course, and scores deservingly ... it''s just that i think it should be freighted with it''s history. E', '2005-01-26 16:46:29.000000', NULL, 0),
(1133963, 135276, 16253, '<td valign="top">knew this one would do well, congratulations on the blue</td>', 'knew this one would do well, congratulations on the blue', '2005-01-26 18:47:17.000000', NULL, 0),
(1134703, 136663, 30364, '<td valign="top">Jeremy,<br/>Congratulations on the success of this very fine image.  I may have under-voted it at 7 the first time round ... now that I have had a second look I see even more good qualities.  The very nice shadows at the outer edge of the arches and down the pillars is one more positive feature I failed to give due credit for during the challenge.  I think 8 might have been a better score.  I am interested in the conflicting views about the inclusion of the person''s figure, expressed in the comments below.  I have tried the shot with and without, and I have no doubt you were certainly correct to include her.  The figure gives both scale and life to the image.  I can almost hear her footsteps!  So well done.  I learned quite a bit from studying your image. Thanks.  Paul.</td>', 'Jeremy,Congratulations on the success of this very fine image.  I may have under-voted it at 7 the first time round ... now that I have had a second look I see even more good qualities.  The very nice shadows at the outer edge of the arches and down the pillars is one more positive feature I failed to give due credit for during the challenge.  I think 8 might have been a better score.  I am interested in the conflicting views about the inclusion of the person''s figure, expressed in the comments below.  I have tried the shot with and without, and I have no doubt you were certainly correct to include her.  The figure gives both scale and life to the image.  I can almost hear her footsteps!  So well done.  I learned quite a bit from studying your image. Thanks.  Paul.', '2005-01-27 02:42:19.000000', NULL, 0),
(1134876, 137190, 8682, '<td valign="top">Critique Club Comment,<br/> <br/>This is an amazing picture about architecture playing with reflections. I really like the simmetry on this image. Perhaps, the only thing I´d probably like to see is a little more focus on reflections, but by the other side this is not important in reflections. Another thing, it would be good for your image, it would be more contrast to get a stronger impact in the reflections. <br/> <br/>The composition, as I said you, is pretty good. Good use of the simmetry (it would be a good example for three challenge). Also, good use of the reflections to get more impact to the viewer.<br/> <br/>Just a beatiful image and one of the more important to me, a different image thanks to the use of reflections. <br/> <br/>Congrats for a good pic and keep the good work.<br/> <br/>Alexis<br/> <br/>PD. All I told you about this image is just my opinion. If you want to comment me something about it, just send me a PM or MSM me.</td>', 'Critique Club Comment, This is an amazing picture about architecture playing with reflections. I really like the simmetry on this image. Perhaps, the only thing I´d probably like to see is a little more focus on reflections, but by the other side this is not important in reflections. Another thing, it would be good for your image, it would be more contrast to get a stronger impact in the reflections.  The composition, as I said you, is pretty good. Good use of the simmetry (it would be a good example for three challenge). Also, good use of the reflections to get more impact to the viewer. Just a beatiful image and one of the more important to me, a different image thanks to the use of reflections.  Congrats for a good pic and keep the good work. Alexis PD. All I told you about this image is just my opinion. If you want to comment me something about it, just send me a PM or MSM me.', '2005-01-27 06:17:48.000000', NULL, 0),
(1134890, 136729, 8682, '<td valign="top">Critique Club Comment:<br/> <br/>First of all, just advice you all I comment about this image is just my opinion and If you want to comment me something about it, you can send me a PM or MSM me.<br/> <br/>The first thing, I don´t like in this image is the size, I think it´s too small. It would be better if you had been submitted it in 640 x 480. Usually, when you see a too small image, you didn´t get a positive impact, because you didn´t see all the details of the image. In this image, just see a good image, but not a great image.<br/> <br/>Another thing, I´d try to change is the focus, the focus isn´t enough to show us the details of the house. Just, one thing more, I´d like to see all the house. <br/> <br/>If you can correct a few things in this image, it has enough potential to be a great image. Just do it!<br/> <br/>Keep the good work, you has only to improve somethings to get great images.<br/> <br/>Alexis<br/></td>', 'Critique Club Comment: First of all, just advice you all I comment about this image is just my opinion and If you want to comment me something about it, you can send me a PM or MSM me. The first thing, I don´t like in this image is the size, I think it´s too small. It would be better if you had been submitted it in 640 x 480. Usually, when you see a too small image, you didn´t get a positive impact, because you didn´t see all the details of the image. In this image, just see a good image, but not a great image. Another thing, I´d try to change is the focus, the focus isn´t enough to show us the details of the house. Just, one thing more, I´d like to see all the house.  If you can correct a few things in this image, it has enough potential to be a great image. Just do it! Keep the good work, you has only to improve somethings to get great images. Alexis', '2005-01-27 06:29:38.000000', NULL, 0),
